import{_ as a}from"./chunks/phenix-save-manifest.CmJw0V-G.js";import{_ as t,c as o,o as i,ag as n}from"./chunks/framework.DZ_cNctr.js";const s="/docs/screenshots/phenix-plate-overview.png",r="/docs/screenshots/phenix-plate-panel.png",l="/docs/screenshots/phenix-plate-channels.png",b=JSON.parse('{"title":"Opera Phenix Plates in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Opera Phenix plates from Harmony V5 and V6 in your browser: every well and field, from a folder, a zip or S3. Free, no conversion.","frontmatter":{"title":"Opera Phenix Plates in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Opera Phenix plates from Harmony V5 and V6 in your browser: every well and field, from a folder, a zip or S3. Free, no conversion."},"headers":[],"relativePath":"guides/opera-phenix-plates.md","filePath":"guides/opera-phenix-plates.md"}'),h={name:"guides/opera-phenix-plates.md"};function d(p,e,m,c,f,g){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="opera-phenix-plates-in-the-browser" tabindex="-1">Opera Phenix Plates in the Browser <a class="header-anchor" href="#opera-phenix-plates-in-the-browser" aria-label="Permalink to &quot;Opera Phenix Plates in the Browser&quot;">​</a></h1><p>Open the plates Harmony exports from your Opera Phenix, as they are. Nothing to convert, nothing to upload. Move through every well and field. The Opera Phenix plates of the Cell Painting Gallery open this way, such as the JUMP Cell Painting pilot plate CPJUMP1. <a href="https://www.find-nuclei.com/blog/opera-phenix-plates-in-the-browser" target="_blank" rel="noreferrer">Opera Phenix Plates in the Browser</a> tells the story on our blog.</p><p><img width="2880" height="1800" src="'+s+`" alt="JUMP Cell Painting plate BR00116991 open in field view on well A/1, field 0, with Alexa 488 and HOECHST 33342 cells on the canvas, the Field / Well / Plate toggle with Well and Plate greyed out, the Opera Phenix note, the well navigator reading Well A/1, 1 of 384, and the 384-well picker" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="what-you-need" tabindex="-1">What You Need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What You Need&quot;">​</a></h2><p>The folder Harmony exported: the index file and the images next to it. Exports from Harmony V5 (<code>Index.idx.xml</code>) and Harmony V6 (<code>Index.xml</code>) both open.</p><p>The folder can be on your computer, or at a web address such as a public S3 bucket. Images load as you look at them.</p><h2 id="how-it-opens" tabindex="-1">How It Opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How It Opens&quot;">​</a></h2><ul><li><strong>A folder on your disk</strong>, in Chrome and Edge. See <a href="#opening-a-plate-from-disk">Opening a plate from disk</a>.</li><li><strong>One zip</strong>, with or without compression, in any browser, from your disk or its address. See <a href="#from-a-zip">From a zip</a>.</li><li><strong>An address</strong>: <code>https://</code> or <code>s3://</code>. See <a href="#opening-a-plate-from-the-web">Opening a plate from the web</a>.</li></ul><h2 id="opening-a-plate-from-the-web" tabindex="-1">Opening a plate from the web <a class="header-anchor" href="#opening-a-plate-from-the-web" aria-label="Permalink to &quot;Opening a plate from the web&quot;">​</a></h2><p>Open the <strong>Open</strong> dialog, choose <strong>From URL</strong> and paste one of these:</p><ul><li>the folder that holds the plate (the measurement folder),</li><li>the folder that holds the index (often <code>Images/</code>),</li><li>or the address of <code>Index.idx.xml</code> or <code>Index.xml</code> itself.</li></ul><p>Given a folder, the viewer looks for <code>Index.idx.xml</code> first, then <code>Index.xml</code>.</p><p>An <code>https://</code> address and an <code>s3://</code> address both work. Here is a JUMP Cell Painting plate in both forms:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cellpainting-gallery.s3.amazonaws.com/cpg0000-jump-pilot/source_4/images/2020_11_04_CPJUMP1/images/BR00116991__2020-11-05T19_51_35-Measurement1/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>s3://cellpainting-gallery/cpg0000-jump-pilot/source_4/images/2020_11_04_CPJUMP1/images/BR00116991__2020-11-05T19_51_35-Measurement1/</span></span></code></pre></div><p>A Harmony V6 measurement opens the same way. Here is one from the Cell Painting Gallery&#39;s <code>cpg0002-jump-scope</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s3://cellpainting-gallery/cpg0002-jump-scope/source_4/images/2020_11_16_Scope1_PE/images/CPBroadPhenixC1PlaneP1__C_BIN2_1P_2020-11-09T10_37_04-Measurement1/</span></span></code></pre></div><p>Two V6 measurements are in the Example Gallery under Cell Painting Gallery.</p><p>The viewer looks in the folder you give it and its <code>Images/</code> folder, not deeper. Some measurements sit inside a grouping folder. Open the measurement folder itself.</p><p>A bucket name with a dot in it works as <code>s3://</code> in us-east-1. In any other region, paste its regional https address instead: <code>https://s3.&lt;region&gt;.amazonaws.com/&lt;bucket&gt;/...</code>.</p><h2 id="opening-a-plate-from-disk" tabindex="-1">Opening a plate from disk <a class="header-anchor" href="#opening-a-plate-from-disk" aria-label="Permalink to &quot;Opening a plate from disk&quot;">​</a></h2><p>Open the <strong>Open</strong> dialog, go to <strong>Local Files</strong> and click <strong>Choose Data Folder</strong>. Pick the measurement folder or the folder that holds the index, whatever its name. Nothing leaves your computer.</p><p>Folders open in Chrome and Edge, as for any dataset folder. Safari and Firefox cannot open folders. See <a href="./local-files.html">Local Files</a> for the details.</p><h3 id="from-a-zip" tabindex="-1">From a zip <a class="header-anchor" href="#from-a-zip" aria-label="Permalink to &quot;From a zip&quot;">​</a></h3><p>Zip the measurement folder, or its contents, and open the zip from your disk or by its address, in any browser. Safari and Firefox open a plate this way. With or without compression both work: <code>zip -0 -r plate.zip Measurement/</code> makes the quickest archive to open. The <code>__MACOSX</code> copies a Finder zip adds are skipped.</p><h2 id="what-to-expect" tabindex="-1">What to expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to expect&quot;">​</a></h2><p>The plate opens as soon as the viewer has read the start of the index, about 1 MB. The whole index can be tens of megabytes. A progress line counts the megabytes while it reads.</p><p>The second time, the plate opens at once. The viewer keeps what it learned in the browser&#39;s storage. <strong>Clear All Data</strong> on the start screen removes it.</p><p>The viewer reads only the start of the index. If an image is missing or cannot be read, that channel is left out of that field and the other channels still show.</p><p>When every channel of a field is missing, the canvas says so instead of showing black. From the web it reads &quot;Images for B/3, field 0 could not be loaded.&quot; From disk it reads &quot;No images for B/3, field 0 in this folder.&quot;</p><h2 id="moving-through-the-plate" tabindex="-1">Moving through the plate <a class="header-anchor" href="#moving-through-the-plate" aria-label="Permalink to &quot;Moving through the plate&quot;">​</a></h2><p>The plate opens in field view on the first well that holds images. The panel is titled with the plate name from the index, such as BR00116991. The well navigator steps through the wells that are present, and the well picker below it jumps to any of them. Wells with no images are skipped.</p><p>Opened from disk, the viewer also checks which images the folder holds. A well the index lists with no images in the folder is grey in the well picker, with the tooltip &quot;No images in this folder&quot;. Its fields read &quot;(no images)&quot; in the field dropdown.</p><p>When the plate has several fields, Z planes or timepoints, the field dropdown and the Z and T sliders move between them. The <a href="./hcs-plates.html">OME-Zarr Plates</a> guide covers the navigator and picker.</p><p><img width="850" height="1000" src="`+r+'" alt="The Navigation tab of plate BR00116991: Field active and Well and Plate greyed out, the note reading Opera Phenix plate: one resolution per field, so Field view only, the well navigator on Well A/1 with the Field 0 dropdown and 1 of 384, and the 384-well picker, 16 by 24, with every well present" style="max-width:425px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="why-there-is-no-plate-or-well-view" tabindex="-1">Why there is no plate or well view <a class="header-anchor" href="#why-there-is-no-plate-or-well-view" aria-label="Permalink to &quot;Why there is no plate or well view&quot;">​</a></h2><p>Fast overviews come from a resolution pyramid. OME-Zarr stores each image several times: at full resolution, then at half, a quarter, and smaller, each cut into small tiles. A plate overview reads only the small levels, a tiny part of the data, and zooming in fetches the detail tiles just for what is on screen.</p><p>A Harmony export has no pyramid. Each field and channel is one TIFF at full resolution, about 2.5 MB on CPJUMP1. An overview of that plate would mean downloading all 27,648 TIFFs, around 70 GB, and shrinking them in the browser. So these plates open one field at a time: eight channels for a field of CPJUMP1, about 20 MB.</p><p>Want plate and well views? Convert the plate to OME-Zarr. <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">How to Convert Any Microscopy File to OME-Zarr</a> shows how.</p><p>Field view works as for any image: zoom, pan, channels, contrast.</p><h2 id="channels-and-colours" tabindex="-1">Channels and colours <a class="header-anchor" href="#channels-and-colours" aria-label="Permalink to &quot;Channels and colours&quot;">​</a></h2><p>Channels take their names from the index. Each one is coloured by its emission wavelength. Brightfield channels are grey and start switched off, so the first view shows the fluorescence. Turn them on in the channel panel. The <a href="./channels.html">Channels</a> guide covers the rest.</p><p><img width="850" height="2180" src="'+l+'" alt="View Options, Channels (8), on plate BR00116991: Alexa 647 and Alexa 568 switched off, 488 long, Alexa 488 and HOECHST 33342 switched on with their contrast sliders, and Brightfield H, Brightfield L and Brightfield switched off" style="max-width:392px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="the-plate-manifest" tabindex="-1">The plate manifest <a class="header-anchor" href="#the-plate-manifest" aria-label="Permalink to &quot;The plate manifest&quot;">​</a></h2><p>Behind every Harmony plate the viewer builds a plate manifest: a small JSON file that names the plate, its wells, fields, planes, timepoints and channels, the image size and pixel size, and the file name of every image.</p><p>To keep one, open <strong>Info</strong> in the toolbar and click <strong>Save plate manifest</strong>. The viewer first reads the whole index, which can take a minute on a large plate, and then saves a complete manifest.</p><p><img width="2880" height="1800" src="'+a+'" alt="The Image Information dialog for plate BR00116991, series A/1/0: 1080 by 1080 pixels, uint16, 0.5980 µm pixels, 8 channels, 1 resolution, stored remotely at an s3:// address in the Cell Painting Gallery, with the Save plate manifest button at the bottom" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>A saved manifest opens the plate on its own, from its web address in <strong>From URL</strong>. The plate opens at once, with no index to read.</p><ul><li>A manifest saved from a web plate names its images folder, so it can sit anywhere on the web.</li><li>A manifest saved from a folder on disk names no images folder. Put it in the <code>Images/</code> folder next to the TIFFs, then open its address. A manifest file does not open from disk; open the folder instead.</li></ul><p>The format is published as a JSON Schema: <a href="https://find-nuclei.github.io/schemas/plate-manifest/v1.json" target="_blank" rel="noreferrer">https://find-nuclei.github.io/schemas/plate-manifest/v1.json</a>.</p><h2 id="publishing-a-plate" tabindex="-1">Publishing a plate <a class="header-anchor" href="#publishing-a-plate" aria-label="Permalink to &quot;Publishing a plate&quot;">​</a></h2><p>Showing a plate with a paper, a figure or a blog post? Publish its manifest. A published manifest opens the plate without reading its index, so your readers see it at once. <a href="./remote-urls.html#plate-manifest">How to publish a plate</a>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>No flat-field correction yet. Images show as recorded.</li><li>Treatment names from Harmony&#39;s assay layout are not shown yet. Wells show their position only.</li><li>The embedded viewer does not open these plates. Use the full viewer.</li></ul><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',54)])])}const x=t(h,[["render",d]]);export{b as __pageData,x as default};
